import{_ as t,a as s,o as a,a4 as i}from"./chunks/framework.-FZumj2l.js";const k=JSON.parse('{"title":"Build with AI","description":"","frontmatter":{"outline":false},"headers":[],"relativePath":"api/build-with-ai.md","filePath":"api/build-with-ai.md","lastUpdated":1783327468000}'),l={name:"api/build-with-ai.md"};function o(n,e,d,h,r,p){return a(),s("div",null,e[0]||(e[0]=[i('<h1 id="build-with-ai" tabindex="-1">Build with AI <a class="header-anchor" href="#build-with-ai" aria-label="Permalink to &quot;Build with AI&quot;">​</a></h1><p>This documentation is built to be consumed by AI coding agents (Claude Code, Cursor, Windsurf, and others) as well as humans. If you&#39;re building an app on the Bagisto API — or extending the API itself — with an AI assistant, point it at the resources below.</p><p><strong>Recommended order for an AI agent:</strong> install the skills below → open <a href="/llms.txt"><code>/llms.txt</code></a> to map the API → follow the <a href="/api/workflows/">Workflows</a> for the exact call-sequence → open the linked endpoint page for each request/response shape.</p><h2 id="llms-txt-—-the-machine-readable-index" tabindex="-1"><code>llms.txt</code> — the machine-readable index <a class="header-anchor" href="#llms-txt-—-the-machine-readable-index" aria-label="Permalink to &quot;`llms.txt` — the machine-readable index&quot;">​</a></h2><p>A single file lists every documented endpoint with a one-line description and a link, so an agent can discover the whole API surface in one fetch:</p><ul><li><strong>Index:</strong> <a href="/llms.txt"><code>/llms.txt</code></a> — every Shop and Admin endpoint, grouped by transport and menu.</li><li><strong>Full content:</strong> <a href="/llms-full.txt"><code>/llms-full.txt</code></a> — the complete documentation concatenated into one file for full ingestion.</li></ul><p>These follow the <a href="https://llmstxt.org" target="_blank" rel="noreferrer">llms.txt convention</a>. An agent should fetch <code>llms.txt</code> first to map the surface, then open the specific endpoint page for the exact request and response shape.</p><h2 id="agent-skills" tabindex="-1">Agent skills <a class="header-anchor" href="#agent-skills" aria-label="Permalink to &quot;Agent skills&quot;">​</a></h2><p>The <a href="https://github.com/bagisto/agent-skills" target="_blank" rel="noreferrer"><code>bagisto/agent-skills</code></a> repository packages Bagisto&#39;s build-rules as installable <strong>agent skills</strong> — domain-specific instructions that teach an agent how to build on and extend the API. Install these first, then follow the <a href="/api/workflows/">Workflows</a> for the call-sequence.</p><p><strong>Building an app that consumes the API:</strong></p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> skills</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> bagisto/agent-skills</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --skill</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;bagisto-api-shop&quot;</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> skills</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> bagisto/agent-skills</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --skill</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;bagisto-api-admin&quot;</span></span></code></pre></div><p><strong>Extending the API itself (custom endpoints):</strong></p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> skills</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> bagisto/agent-skills</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --skill</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;bagisto-api-develop&quot;</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> skills</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> bagisto/agent-skills</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --skill</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;pest-testing&quot;</span></span></code></pre></div><p><strong>Everything:</strong></p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> skills</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> bagisto/agent-skills</span></span></code></pre></div><p>Target a specific agent with <code>-a claude-code</code> or <code>-a cursor</code>.</p><table tabindex="0"><thead><tr><th>Skill</th><th>Use it to</th></tr></thead><tbody><tr><td><code>bagisto-api-shop</code></td><td>Build a storefront / customer app on the Shop API</td></tr><tr><td><code>bagisto-api-admin</code></td><td>Build an admin / back-office app on the Admin API</td></tr><tr><td><code>bagisto-api-develop</code></td><td>Add or extend a REST/GraphQL endpoint in the API package</td></tr><tr><td><code>pest-testing</code></td><td>Write the REST + GraphQL tests that lock both transports</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">Grouped skills</p><p>The API skills live under <code>skills/api-platform-development/</code> and share a <code>reference/</code> tree. Installing one pulls the shared reference automatically, so prefer installing the pack (or the grouped skill) over copying a single file.</p></div><h2 id="optional-docs-mcp-server" tabindex="-1">Optional: docs MCP server <a class="header-anchor" href="#optional-docs-mcp-server" aria-label="Permalink to &quot;Optional: docs MCP server&quot;">​</a></h2><p>Bagisto also provides an <strong>optional</strong> <a href="https://modelcontextprotocol.io" target="_blank" rel="noreferrer">MCP</a> server that lets an agent search this documentation on demand. It indexes the API pages and exposes tools like <code>search_api_docs</code>, <code>list_endpoints</code>, and <code>get_doc</code>.</p><ul><li><strong>Repository:</strong> <a href="https://github.com/bagisto/mcp" target="_blank" rel="noreferrer"><code>bagisto/mcp</code></a> — setup and the exact <code>claude mcp add</code> command are in the repo README.</li></ul><p>You don&#39;t need the MCP server to build with AI — <a href="/llms.txt"><code>/llms.txt</code></a> and <a href="/llms-full.txt"><code>/llms-full.txt</code></a> cover the same need statically.</p><h2 id="how-an-agent-should-use-these-docs" tabindex="-1">How an agent should use these docs <a class="header-anchor" href="#how-an-agent-should-use-these-docs" aria-label="Permalink to &quot;How an agent should use these docs&quot;">​</a></h2><ol><li>Fetch <a href="/llms.txt"><code>/llms.txt</code></a> to discover the endpoint you need.</li><li>Open that endpoint&#39;s page for the exact request body, response shape, and errors — <strong>never guess a payload</strong>.</li><li>For end-to-end flows, follow the <a href="/api/workflows/">Workflows</a> — ordered walkthroughs that chain real endpoint calls.</li><li>Mind the GraphQL rules: select <strong>result fields</strong> (<code>cartId</code>, <code>orderId</code>, <code>success</code>) on action mutations — not <code>id</code>; inputs are camelCase; the Shop and Admin GraphQL endpoints are separate.</li></ol>',24)]))}const g=t(l,[["render",o]]);export{k as __pageData,g as default};
